import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"事件 API","description":"","frontmatter":{},"headers":[],"relativePath":"modules/storage/events.md","filePath":"modules/storage/events.md","lastUpdated":0}`),a={name:`modules/storage/events.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="事件-api" tabindex="-1">事件 API <a class="header-anchor" href="#事件-api" aria-label="Permalink to “事件 API”">​</a></h1><p>Storage 事件位于 <code>emaki.jiuwu.craft.storage.api.event</code>，是玩家 owner thread 上的同步可取消 Bukkit 事件。字段是不可变事务快照，没有可修改业务字段。</p><table tabindex="0"><thead><tr><th>事件</th><th>触发时机</th><th>取消效果</th><th>runtime 路径</th></tr></thead><tbody><tr><td><code>StorageDepositEvent</code></td><td>capacity 预检后、库存移除（若有）和 entry credit 前</td><td>阻止移除与仓库增加</td><td>transaction deposit、<code>depositDirect</code>，包括 <code>depositAsync(..., source=api)</code>、GUI/命令/action</td></tr><tr><td><code>StorageWithdrawEvent</code></td><td>计算可取数量后、entry debit 与物品交付前</td><td>阻止扣减与交付</td><td><code>StorageTransactionService.withdraw</code>，包括 <code>withdrawAsync(..., source=api)</code> 与 GUI/命令/action</td></tr><tr><td><code>StorageUnlockEvent</code></td><td>总价计算后、货币/物品扣费与 purchased slots 增加前</td><td>阻止全部扣费和解锁</td><td>付费 unlock service；管理型 <code>grantSlotsAsync</code> 不触发</td></tr><tr><td><code>StorageBatchEvent</code></td><td>批量原子操作提交前、任何 escrow 扣除与写入前</td><td>阻止整批操作；批内不再单独触发 Deposit/Withdraw 事件</td><td><code>applyBatchAsync</code></td></tr></tbody></table><p>Deposit/withdraw/unlock 包含 playerId、克隆并规范化的 template、requested amount、source（<code>gui</code>/<code>command</code>/<code>api</code>/<code>action</code>）；withdraw 另有 stored amount；unlock 包含 slots、购买前数量和 <code>currencyCost</code>（<strong>仅货币成本</strong>，物品代价不在此事件中反映）。Batch 事件包含 playerId、操作列表（<code>ops()</code> 返回 <code>List&lt;StorageBatchOp&gt;</code>）、<code>allOrNothing()</code> 标志与 source。访问器一律是 record 风格、不带 <code>get</code> 前缀。异步 facade 只负责提交/调度，事件仍在实际 owner-thread transaction 中同步触发；future callback 不继承该线程保证。</p>`,4)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};